import math

def db_topla(seviyeler):
    toplam = 0.0
    for L in seviyeler:
        toplam += 10 ** (L / 10.0)
    return 10 * math.log10(toplam)

def mesafe_azalim(L1, r1, r2):
    return L1 - 20 * math.log10(r2 / r1)

print("82 + 78 dB = " + str(round(db_topla([82.0, 78.0]), 2)) + " dB")
print("82 + 82 dB = " + str(round(db_topla([82.0, 82.0]), 2)) + " dB")
print("dort adet 82 dB = " + str(round(db_topla([82.0] * 4), 2)) + " dB")
print("aritmetik toplam (YANLIS) = " + str(82 + 78) + " dB")
print("5 m'de 92 dB -> 40 m'de " + str(round(mesafe_azalim(92.0, 5.0, 40.0), 2)) + " dB")
